// @ts-check
/**
 * Real-browser tests. Nothing in the playback path is mocked: the app is the production build, the media is real
 * (e2e/fixtures/media, generated by scripts/make-test-video.sh), served over HTTP with Range support.
 * Only TMDB metadata is stubbed (it says nothing about playability). See docs/STREAMING.md#testing.
 *
 * Test films (see e2e/fixtures/catalog.json): 9001 progressive MP4/WebM + subtitles, 9002 HLS, 9003 403 (expired link),
 * 9004 404 (missing file), 9005 invalid source, 9006 past expiresAt, 9007 restricted, 9008 trailer only, 9009 nothing.
 */
const { test, expect } = require("@playwright/test");

const BASE = "/movie-app";
const slug = (id) => `${BASE}/movie/${id}-cinema-test-film-${id}`;
const H264 = 'video/mp4; codecs="avc1.64000B, mp4a.40.2"';
const FILM_DURATION = 180;

/** Runs before the app: remembers every <video> and MediaSource so teardown can be inspected afterwards. */
function instrument() {
  window.__videos = [];
  window.__mediaSources = [];
  const create = document.createElement.bind(document);
  document.createElement = (tag, options) => {
    const el = create(tag, options);
    if (String(tag).toLowerCase() === "video") window.__videos.push(el);
    return el;
  };
  if (window.MediaSource) {
    const Original = window.MediaSource;
    window.MediaSource = class extends Original {
      constructor(...args) {
        super(...args);
        window.__mediaSources.push(this);
      }
    };
  }
}

const video = (page) => page.locator("video.player-video");
const snap = (page) =>
  video(page).evaluate((v) => ({ t: v.currentTime, d: v.duration, paused: v.paused, ended: v.ended, ready: v.readyState, net: v.networkState, err: v.error ? v.error.code : null, src: v.currentSrc }));
const progress = (page) => page.evaluate(() => { try { return JSON.parse(localStorage.getItem("cinema:progress:v1")); } catch { return "unparseable"; } });

async function browserCodecs(page) {
  return page.evaluate((h264) => {
    const v = document.createElement("video");
    return { h264: Boolean(v.canPlayType(h264)), mseH264: Boolean(window.MediaSource && window.MediaSource.isTypeSupported('video/mp4; codecs="avc1.64000B,mp4a.40.2"')) };
  }, H264);
}

/** Console errors and page errors. Tests that deliberately break the network pass `expected` patterns. */
function watchErrors(page, expected = []) {
  const errors = [];
  page.on("console", (m) => {
    if (m.type() !== "error" || expected.some((re) => re.test(m.text()))) return;
    // Chrome logs the 404 status of a *document* here. Deep links answer 404 on purpose (GitHub Pages behaviour, see server.js).
    const url = m.location().url || "";
    if (/Failed to load resource.*404/.test(m.text()) && /\/movie-app\/[^.]*$/.test(url)) return;
    errors.push(`${m.text()} [${url}]`);
  });
  page.on("pageerror", (e) => errors.push(`pageerror: ${e.message}`));
  return errors;
}

/** The real user path: film page -> "Watch movie" (which asks the player to start). */
async function startFromDetails(page, id = 9001) {
  await page.goto(slug(id));
  await page.getByRole("link", { name: /Watch movie|Resume from/ }).click();
  await expect(page).toHaveURL(new RegExp(`/watch/${id}`));
  await expect(video(page)).toBeVisible();
}

const waitForPlaying = async (page, seconds = 1.5) => {
  await expect.poll(async () => { const s = await snap(page); return !s.paused && s.t > seconds && s.ready >= 3; }, { timeout: 20_000 }).toBe(true);
};

test.beforeEach(async ({ page, request }) => {
  await request.get("/__stats/reset");
  await page.addInitScript(instrument);
  await page.route(/youtube/, (r) => r.abort()); // the trailer embed needs the internet; the sandbox has none
});

test.describe("availability is truthful", () => {
  const cases = [
    [9001, /Watch in full/, true],
    [9002, /Watch in full/, true],
    [9005, /Source misconfigured/, false],
    [9006, /Link expired/, false],
    [9007, /Restricted/, false],
    [9008, /Trailer only/, false],
    [9009, /Not streaming/, false],
  ];
  for (const [id, label, canWatch] of cases) {
    test(`film ${id}: ${label}`, async ({ page }) => {
      await page.goto(slug(id));
      await expect(page.locator(".availability")).toContainText(label);
      await expect(page.getByRole("link", { name: /Watch movie/ })).toHaveCount(canWatch ? 1 : 0);
    });
  }

  test("a trailer is labelled as a trailer and never offers the film", async ({ page }) => {
    await page.goto(slug(9008));
    await page.getByRole("button", { name: "Watch trailer" }).click();
    await expect(page.getByRole("dialog")).toContainText("This is a trailer, not the full film.");
    await page.keyboard.press("Escape");
    await expect(page.getByRole("dialog")).toBeHidden();
    await page.goto(`${BASE}/watch/9008`);
    await expect(page.getByRole("heading", { name: "Trailer only" })).toBeVisible();
    await expect(video(page)).toHaveCount(0);
  });

  test("unplayable sources never mount a player", async ({ page }) => {
    for (const id of [9005, 9006, 9007, 9009]) {
      await page.goto(`${BASE}/watch/${id}`);
      await expect(page.locator(".watch-blocked")).toBeVisible();
      await expect(video(page)).toHaveCount(0);
    }
  });
});

test.describe("full-length playback (progressive)", () => {
  test("loads, plays past the start, with no console errors", async ({ page }) => {
    const errors = watchErrors(page);
    await startFromDetails(page);
    const codecs = await browserCodecs(page);
    await waitForPlaying(page, 6);
    const s = await snap(page);
    expect(s.err).toBeNull();
    expect(s.d).toBeGreaterThan(FILM_DURATION - 1);
    expect(s.d).toBeLessThan(FILM_DURATION + 1);
    // Source selection honours the declared codecs: H.264 where decodable, otherwise the WebM listed second.
    expect(s.src).toMatch(codecs.h264 ? /film\.mp4$/ : /film\.webm$/);
    expect(errors).toEqual([]);
  });

  test("seeks forward and back with real range requests, pauses and resumes", async ({ page, request }) => {
    await startFromDetails(page);
    await waitForPlaying(page, 2);
    await video(page).focus();

    // Forward: the player's own shortcut (L = +10 s).
    const before = (await snap(page)).t;
    await page.keyboard.press("l");
    await expect.poll(async () => (await snap(page)).t, { timeout: 10_000 }).toBeGreaterThanOrEqual(before + 9);
    // Far jump (what dragging the seek bar does) and back again.
    await video(page).evaluate((v) => { v.currentTime = 120; });
    await expect.poll(async () => { const s = await snap(page); return s.t > 120.5 && !s.paused; }, { timeout: 15_000 }).toBe(true);
    await page.keyboard.press("j");
    await expect.poll(async () => (await snap(page)).t, { timeout: 10_000 }).toBeLessThan(120);
    await video(page).evaluate((v) => { v.currentTime = 20; });
    await expect.poll(async () => { const s = await snap(page); return s.t >= 20 && s.t < 40 && s.ready >= 3; }, { timeout: 15_000 }).toBe(true);

    // Pause (K) holds position; resume (K) moves it on.
    await page.keyboard.press("k");
    await expect.poll(async () => (await snap(page)).paused).toBe(true);
    const held = (await snap(page)).t;
    await page.waitForTimeout(1500);
    expect(Math.abs((await snap(page)).t - held)).toBeLessThan(0.1);
    await page.keyboard.press("k");
    await expect.poll(async () => (await snap(page)).t, { timeout: 10_000 }).toBeGreaterThan(held + 1);

    const stats = await (await request.get("/__stats")).json();
    // The ~1 MB fixture is small enough for Chrome to buffer whole, so a later byte offset is not guaranteed; what is
    // guaranteed is that the browser talked Range to the server (seeking depends on it). Seeks themselves are proven
    // above by the position the film then really plays from.
    expect(stats.rangeRequests).toBeGreaterThan(0);
  });

  test("saves progress, offers resume, and Continue watching resumes directly", async ({ page }) => {
    await startFromDetails(page);
    await waitForPlaying(page, 1);
    await video(page).evaluate((v) => { v.currentTime = 60; });
    await expect.poll(async () => (await snap(page)).t, { timeout: 15_000 }).toBeGreaterThan(61);
    await video(page).focus();
    await page.keyboard.press("k"); // pausing persists the position
    await expect.poll(async () => (await progress(page))?.["9001"]?.position, { timeout: 5_000 }).toBeGreaterThan(59);
    const saved = (await progress(page))["9001"];
    expect(saved.position).toBeLessThan(75);
    expect(saved.duration).toBeGreaterThan(FILM_DURATION - 1);

    // Direct visit asks; choosing Resume lands at the saved position and plays.
    await page.reload();
    await expect(page.getByText("Pick up where you left off?")).toBeVisible();
    await page.getByRole("button", { name: /^Resume at/ }).click();
    await expect.poll(async () => { const s = await snap(page); return !s.paused && Math.abs(s.t - saved.position) < 4; }, { timeout: 15_000 }).toBe(true);
    await video(page).focus();
    await page.keyboard.press("k");

    // Home's Continue watching card resumes with no prompt.
    await page.goto(`${BASE}/`);
    await page.getByRole("link", { name: /^Resume Cinema Test Film 9001/ }).click();
    await expect(page).toHaveURL(/\/watch\/9001\?resume=1/);
    await expect(page.getByText("Pick up where you left off?")).toHaveCount(0);
    await expect.poll(async () => { const s = await snap(page); return !s.paused && s.t > saved.position - 4; }, { timeout: 15_000 }).toBe(true);
  });

  test("reaches the actual end, shows the completion state and clears progress", async ({ page }) => {
    await startFromDetails(page);
    await waitForPlaying(page, 1);
    await video(page).evaluate((v) => { v.currentTime = 40; });
    await expect.poll(async () => (await snap(page)).t, { timeout: 15_000 }).toBeGreaterThan(41);
    await video(page).focus();
    await page.keyboard.press("k");
    await expect.poll(async () => Boolean((await progress(page))?.["9001"]), { timeout: 5_000 }).toBe(true);
    await page.keyboard.press("k");
    // Jump to the final seconds, then let the film really play out to its end.
    await video(page).evaluate((v) => { v.currentTime = v.duration - 6; });
    await expect.poll(async () => (await snap(page)).ended, { timeout: 30_000 }).toBe(true);
    await expect(page.locator(".player")).toHaveAttribute("data-phase", "ended");
    await expect(page.getByText("That’s the end of Cinema Test Film 9001")).toBeVisible();
    expect((await progress(page))?.["9001"]).toBeUndefined(); // finished films leave Continue watching
  });

  test("subtitle track loads", async ({ page }) => {
    await startFromDetails(page);
    await waitForPlaying(page, 0.5);
    const cues = await video(page).evaluate(async (v) => {
      const track = v.textTracks[0];
      track.mode = "showing";
      for (let i = 0; i < 50 && !(track.cues && track.cues.length); i += 1) await new Promise((r) => setTimeout(r, 100));
      return { count: v.textTracks.length, label: track.label, cues: track.cues ? track.cues.length : 0 };
    });
    expect(cues).toEqual({ count: 1, label: "English", cues: 2 });
  });

  test("whole film in real time (opt-in: E2E_FULL=1)", async ({ page }) => {
    test.skip(!process.env.E2E_FULL, "takes ~3 minutes; run with E2E_FULL=1");
    test.setTimeout(300_000);
    await startFromDetails(page);
    await expect.poll(async () => (await snap(page)).t, { timeout: 60_000 }).toBeGreaterThan(5);
    let midway = null;
    await expect.poll(async () => { const s = await snap(page); if (s.t > 45 && !midway) midway = await progress(page); return s.ended; }, { timeout: 240_000, intervals: [1000] }).toBe(true);
    expect(midway?.["9001"]?.position).toBeGreaterThan(30); // progress was being saved while it played
    const end = await snap(page);
    expect(end.d).toBeGreaterThan(FILM_DURATION - 1);
    expect(end.t).toBeGreaterThan(end.d - 0.5);
    expect((await progress(page))?.["9001"]).toBeUndefined();
  });
});

test.describe("full-length playback (HLS via hls.js)", () => {
  test("plays across several segments", async ({ page }) => {
    const errors = watchErrors(page);
    await page.goto(slug(9002));
    const codecs = await browserCodecs(page);
    test.skip(!codecs.mseH264, "this browser build cannot decode H.264 through Media Source Extensions");
    await page.getByRole("link", { name: /Watch movie/ }).click();
    await waitForPlaying(page, 10); // segments are 4 s: this crosses at least two boundaries
    const s = await snap(page);
    expect(s.src).toMatch(/^blob:/); // attached through MediaSource, i.e. hls.js
    expect(s.err).toBeNull();
    await video(page).evaluate((v) => { v.currentTime = 100; });
    await expect.poll(async () => (await snap(page)).t, { timeout: 15_000 }).toBeGreaterThan(101);
    expect(errors).toEqual([]);
  });

  test("a network failure surfaces, is capped, and Try again resumes where it broke", async ({ page }) => {
    test.setTimeout(120_000);
    await page.goto(slug(9002));
    const codecs = await browserCodecs(page);
    test.skip(!codecs.mseH264, "this browser build cannot decode H.264 through Media Source Extensions");
    const block = (route) => route.abort("connectionreset");
    await page.route(/\/media\/hls\/seg_0(0[3-9]|1\d)\.m4s/, block); // first ~12 s load, then the connection dies
    await page.getByRole("link", { name: /Watch movie/ }).click();
    await expect(page.getByRole("alert")).toContainText("Playback was interrupted", { timeout: 60_000 });
    await expect(page.getByRole("button", { name: "Try again" })).toBeVisible();
    await page.unroute(/\/media\/hls\/seg_0(0[3-9]|1\d)\.m4s/, block);
    await page.getByRole("button", { name: "Try again" }).click();
    await expect.poll(async () => { const s = await snap(page); return !s.paused && s.t > 10; }, { timeout: 30_000 }).toBe(true);
  });
});

test.describe("failures are explained and bounded", () => {
  test("expired link (403) is reported as expired, with no pointless retry", async ({ page }) => {
    await page.goto(`${BASE}/watch/9003`);
    await expect(page.getByRole("alert")).toContainText("This playback link has expired");
    await expect(page.getByRole("button", { name: "Try again" })).toHaveCount(0);
  });

  test("missing file (404): retry is offered at most three times", async ({ page }) => {
    let requests = 0;
    page.on("request", (r) => { if (r.url().endsWith("/media/missing.mp4")) requests += 1; });
    await page.goto(`${BASE}/watch/9004`);
    let clicks = 0;
    for (;;) {
      await expect(page.getByRole("alert")).toContainText("The film couldn’t be loaded");
      const retry = page.getByRole("button", { name: "Try again" });
      if (!(await retry.isVisible())) break;
      clicks += 1;
      expect(clicks).toBeLessThanOrEqual(3);
      await retry.click();
      await page.waitForTimeout(300);
    }
    expect(clicks).toBe(3);
    expect(requests).toBeLessThan(16); // bounded: no infinite retry loop
  });

  test("a browser that can play nothing says so", async ({ page }) => {
    await page.addInitScript(() => {
      HTMLMediaElement.prototype.canPlayType = () => "";
      Object.defineProperty(window, "MediaSource", { value: undefined, configurable: true });
      Object.defineProperty(window, "ManagedMediaSource", { value: undefined, configurable: true });
    });
    await page.goto(`${BASE}/watch/9001`);
    await expect(page.getByRole("alert")).toContainText("This browser can’t play this film");
  });
});

test.describe("player teardown", () => {
  const leaving = async (page) => {
    await page.getByRole("link", { name: "Back to details" }).first().click();
    await expect(page).toHaveURL(/\/movie\//);
    await expect(video(page)).toHaveCount(0);
  };
  const released = (page) => page.evaluate(() => ({
    videos: window.__videos.map((v) => ({ hasSrc: v.hasAttribute("src"), net: v.networkState, ready: v.readyState, paused: v.paused })),
    mediaSources: window.__mediaSources.map((m) => m.readyState),
  }));

  test("progressive: element emptied, connection released, no more downloads", async ({ page, request }) => {
    await startFromDetails(page);
    await waitForPlaying(page, 2);
    await leaving(page);
    const r = await released(page);
    expect(r.videos.length).toBeGreaterThan(0);
    for (const v of r.videos) expect(v).toMatchObject({ hasSrc: false, net: 0, ready: 0, paused: true }); // NETWORK_EMPTY
    await expect.poll(async () => (await (await request.get("/__stats")).json()).active, { timeout: 5_000 }).toBe(0);
    const total = (await (await request.get("/__stats")).json()).mediaRequests;
    await page.waitForTimeout(2500);
    expect((await (await request.get("/__stats")).json()).mediaRequests).toBe(total);
  });

  test("HLS: hls.js destroyed (MediaSource detached), no more segment requests", async ({ page, request }) => {
    await page.goto(slug(9002));
    const codecs = await browserCodecs(page);
    test.skip(!codecs.mseH264, "this browser build cannot decode H.264 through Media Source Extensions");
    await page.getByRole("link", { name: /Watch movie/ }).click();
    await waitForPlaying(page, 2);
    await leaving(page);
    const r = await released(page);
    expect(r.mediaSources.length).toBeGreaterThan(0);
    expect(r.mediaSources.every((s) => s === "closed")).toBe(true);
    for (const v of r.videos) expect(v).toMatchObject({ hasSrc: false, net: 0, paused: true });
    const total = (await (await request.get("/__stats")).json()).mediaRequests;
    await page.waitForTimeout(3000);
    expect((await (await request.get("/__stats")).json()).mediaRequests).toBe(total);
  });
});

test.describe("site behaviour on the production base path", () => {
  test("deep links work through the 404.html fallback; assets load from /movie-app/", async ({ page }) => {
    const bad = [];
    page.on("response", (r) => {
      if (["script", "stylesheet", "image", "font", "fetch", "xhr", "manifest"].includes(r.request().resourceType()) && r.status() >= 400) bad.push(`${r.status()} ${r.url()}`);
    });
    const errors = watchErrors(page);
    const doc = await page.goto(`${BASE}/watch/9001`);
    expect(doc?.status()).toBe(404); // exactly what GitHub Pages answers for a path it has no file for...
    await expect(video(page)).toBeVisible(); // ...and the app still renders it
    await page.goto(`${BASE}/discover`);
    await expect(page.getByRole("heading", { level: 1 })).toBeVisible();
    await page.goto(`${BASE}/no-such-page`);
    await expect(page.getByText("This page isn’t showing")).toBeVisible();
    expect(bad).toEqual([]);
    expect(errors).toEqual([]);
  });

  test("watchlist persists across reloads and survives corrupted storage", async ({ page }) => {
    await page.goto(slug(9001));
    await page.getByRole("button", { name: "Add to watchlist" }).click();
    await page.reload();
    await expect(page.getByRole("button", { name: "In watchlist" })).toHaveAttribute("aria-pressed", "true");
    await page.goto(`${BASE}/watchlist`);
    await expect(page.getByText("Cinema Test Film 9001").first()).toBeVisible();
    await page.evaluate(() => { localStorage.setItem("cinema:watchlist:v1", "{not json"); localStorage.setItem("cinema:progress:v1", "[1,2"); });
    await page.goto(slug(9001));
    await expect(page.getByRole("button", { name: "Add to watchlist" })).toBeVisible();
    await page.goto(`${BASE}/watch/9001`);
    await expect(video(page)).toBeVisible();
  });

  test("phone-sized layout has no horizontal overflow and a visible player", async ({ page }) => {
    await page.setViewportSize({ width: 360, height: 640 });
    await page.goto(`${BASE}/watch/9001`);
    await expect(video(page)).toBeVisible();
    const m = await page.evaluate(() => ({ scroll: document.documentElement.scrollWidth, width: window.innerWidth, video: document.querySelector("video").getBoundingClientRect().width }));
    expect(m.scroll).toBeLessThanOrEqual(m.width);
    expect(m.video).toBeLessThanOrEqual(m.width);
    await expect(video(page)).toHaveAttribute("aria-label", /full film/);
  });
});
